// SPDX-License-Identifier: Apache-2.0
'use client';

import type { ReactElement } from 'react';
import { ZoneLink } from '../zone/zone-link';
import { BRAND_LOGO_ALT, BRAND_LOGO_SRC } from './brand-logo';

export type Brand = {
  /** The product name that follows the logo, for example "IAM". The logo supplies "Paigasus". */
  readonly label: string;
  /** A full path (spec § 6.2). */
  readonly href: string;
};

/**
 * The header's home link: the Paigasus logo, then the product label. The image's alt text and the
 * label together give the link its accessible name, for example "Paigasus IAM".
 *
 * A plain <img>, not next/image: the source is a small data URI, so the image optimizer has
 * nothing to do, and this package must also render outside a Next app (vitest, the e2e fixture).
 */
export function BrandLink({ brand }: { readonly brand: Brand }): ReactElement {
  return (
    <ZoneLink href={brand.href} className="flex items-center gap-2 font-semibold">
      {/* eslint-disable-next-line @next/next/no-img-element -- see the comment above. */}
      <img src={BRAND_LOGO_SRC} alt={BRAND_LOGO_ALT} width={32} height={32} className="size-8 rounded-md" />
      <span>{brand.label}</span>
    </ZoneLink>
  );
}

